from lib import *
N=14
TITLE='חופש הביטוי (א): הלכת קול העם'
SUM=[
h3('14.1 מקומו של חופש הביטוי'),
p('חופש הביטוי הוא אחת הזכויות המרכזיות במשטר דמוקרטי. הוא אינו מנוי במפורש בחוק יסוד: כבוד האדם וחירותו, ובכל זאת הוא מוכר כזכות יסוד בעלת מעמד רם. הכרה זו קדמה לחוקי היסוד של 1992 והתבססה על פסיקה, ובראשה פסק הדין <b>קול העם</b> משנת 1953. בפרק זה נעסוק ביסודות הזכות ובהלכת קול העם. בפרק הבא נעסוק במעמדה החוקתי ובאיזונים מול זכויות ואינטרסים אחרים.'),
h3('14.2 שלושת הרציונלים לחופש הביטוי'),
tbl(['רציונל','תוכן'],[
['חיפוש האמת (שוק הרעיונות)','בתחרות חופשית בין רעיונות האמת תצא לאור'],
['קיום ההליך הדמוקרטי','בחירה מושכלת וביקורת על השלטון דורשות מידע ודעות חופשיים'],
['מימוש עצמי','ביטוי הוא חלק מהאוטונומיה ומהכבוד של הפרט']]),
p('שלושת הרציונלים משלימים זה את זה ומסבירים מדוע מעמדו של חופש הביטוי גבוה. בדרך כלל ביטוי פוליטי הוא בעל ההגנה החזקה ביותר, כי הוא קרוב ביותר לרציונל הדמוקרטי. ביטוי מסחרי, או ביטוי שאין לו ערך ציבורי, יזכה להגנה, אך לרוב חלשה יותר.'),
h3('14.3 הלכת קול העם'),
box('case','קול העם נ׳ שר הפנים (בג"ץ 73/53, פ"ד ז 871, 1953)','שר הפנים סגר זמנית שני עיתונים, "קול העם" ו"אל-אתיחאד", בטענה שמאמרים בהם, שבקרו חריפות את מדיניות הממשלה, מסכנים את שלום הציבור. הסמכות נשענה על פקודת העיתונות, שאפשרה לשר לסגור עיתון אם פרסומו עלול לסכן את שלום הציבור. בית המשפט, מפי השופט אגרנט, ביטל את הסגירה. נקבע שחופש הביטוי הוא יסוד המשטר הדמוקרטי, ושיש לפרש בצמצום סמכות שמגבילה אותו. הוא קבע את מבחן <b>הוודאות הקרובה</b>: אפשר להגביל ביטוי רק אם קיימת ודאות קרובה לפגיעה ממשית בשלום הציבור, ולא די בחשש או בנטייה כללית.'),
p('ההלכה ביצעה איזון בין שני ערכים: חופש הביטוי מול שלום הציבור. בחירת מבחן הוודאות הקרובה, ולא מבחן רופף של "נטייה לפגיעה", פירושה ששלום הציבור אינו יכול להצדיק הגבלה בכל חשש. הדגש הוא על הסתברות גבוהה ועל נזק ממשי. מבחן זה הפך לאבן יסוד, והורחב בהמשך למקרים נוספים.'),
box('tip','טיפ למבחן','כשנשאלים על קול העם, כתוב: (1) העובדות בקצרה; (2) הקביעה שחופש הביטוי הוא יסוד הדמוקרטיה; (3) פרשנות מצמצמת לסמכות המגבילה; (4) מבחן הוודאות הקרובה; (5) הערה שההלכה ניתנה לפני העיגון החוקתי.'),
h3('14.4 הרחבת ההלכה: ביטחון, רגשות ותחומים נוספים'),
box('case','שניצר נ׳ הצנזור הצבאי הראשי (בג"ץ 680/88, 1989)','הצנזור פסל פרסום מאמר עיתונאי בנושא ביטחוני. בית המשפט החיל את מבחן הוודאות הקרובה גם בענייני ביטחון, ופסל את שיקול הדעת הרחב של הצנזור. ההלכה: חופש הביטוי גובר, אלא אם קיימת ודאות קרובה לפגיעה ממשית בביטחון. נקבע שלא די בחשש רחוק.'),
box('case','לאור נ׳ מועצת הסרטים והמחזות (בג"ץ 14/86, 1987)','נדונה סמכות מועצה לאסור הצגת יצירה בטענה לפגיעה ברגשות הציבור. בית המשפט החיל מבחן קרוב לוודאות קרובה גם על פגיעה ברגשות, ודרש פגיעה חמורה וקרובה. פרטי הפרשה לא אומתו במלואם, ולכן יש להסתמך על העיקרון.'),
h3('14.5 הגבלות מקובלות על חופש הביטוי'),
ul('<b>שלום הציבור וביטחון המדינה</b> - לפי מבחן הוודאות הקרובה.','<b>הסתה לגזענות</b> (ס׳ 144ב לחוק העונשין) והסתה לאלימות או לטרור.','<b>לשון הרע</b> - הגנה על שם טוב (נדון בפרק הבא).','<b>פרטיות</b> - איזון בין ביטוי לפרטיות.','<b>בזיון בית משפט</b>, גילוי סודות מדינה והגנה על ההליך השיפוטי.','<b>תוכן גס ופורנוגרפיה</b> - בכפוף למידתיות.'),
box('warn','מלכודות נפוצות',['לטעון שקול העם ניתנה לאחר המהפכה החוקתית - ניתנה ב-1953.','לטעון שמבחן הוודאות הקרובה מקל על הגבלת ביטוי - הוא מקשה.','לחשוב שביטוי פוגעני אינו מוגן - הוא מוגן ודווקא הוא זקוק להגנה.','לבלבל בין שלום הציבור לבין רגשות הציבור: הראשון חמור יותר.']),
h3('14.6 שלד לפתרון שאלה'),
ol('מהו הביטוי, ומי מגביל אותו (חוק, רשות, שר)?','האם יש הסמכה מפורשת? פרש בצמצום.','איזה ערך נוגד: שלום הציבור, ביטחון, שם טוב, פרטיות?','החל מבחן הוודאות הקרובה (או איזון אחר) ובדוק ודאות ונזק.','סכם: האם ההגבלה מידתית, והאם הביטוי הוא פוליטי.'),
box('ex','תרגיל פתור','רשות מנעה הפגנה בטענה שהיא עלולה לעורר מתח. המארגנים הצהירו שההפגנה שלווה. <b>פתרון:</b> מתח כללי אינו ודאות קרובה לפגיעה ממשית בשלום הציבור. לפי קול העם, אין לאסור; אפשר לכל היותר להטיל תנאים שימנעו סיכון קונקרטי.'),
box('key','סיכום הפרק',['שלושה רציונלים: אמת, דמוקרטיה, מימוש עצמי.','קול העם 1953: הוודאות הקרובה.','שניצר: ביטחון; לאור: רגשות.','ביטוי פוגעני מוגן; הגבלות לפי איזון ומידתיות.'])
]
CASES=[
('בג"ץ 73/53 חברת "קול העם" בע"מ נ׳ שר הפנים, פ"ד ז 871 (1953)','שר הפנים סגר את העיתונים קול העם ואל-אתיחאד בשל ביקורת חריפה על הממשלה.','חופש הביטוי הוא יסוד הדמוקרטיה; סמכות מגבילה תפורש בצמצום; מבחן הוודאות הקרובה לפגיעה ממשית בשלום הציבור. למבחן: הלכה מכוננת.'),
('בג"ץ 680/88 שניצר נ׳ הצנזור הצבאי הראשי (1989)','הצנזור פסל מאמר בנושא ביטחוני.','גם בביטחון נדרשת ודאות קרובה לפגיעה ממשית. למבחן: הרחבת קול העם.'),
('בג"ץ 14/86 לאור נ׳ מועצת הסרטים והמחזות (1987)','הגבלת הצגה בשל פגיעה ברגשות הציבור.','נדרשת פגיעה חמורה וקרובה ברגשות. למבחן: הרחבה לרגשות. פרטי הפרשה לא אומתו.'),
('שלושת רציונלי חופש הביטוי','מסגרת תיאורטית.','חיפוש האמת, ההליך הדמוקרטי והמימוש העצמי מסבירים את מעמדו הרם של הביטוי. למבחן: להזכיר את שלושתם.')
]
QS=[
Q('מהו פסק הדין המכונן של חופש הביטוי בישראל?','קול העם',['בנק המזרחי','קעדאן','חורב'],'פסק הדין קול העם (1953) הוא הפסק המכונן של חופש הביטוי, ובו נקבע מבחן הוודאות הקרובה. בנק המזרחי עוסק במעמד חוקי היסוד, קעדאן בשוויון בהקצאת קרקע וחורב בדת ותנועה, ולכן אינם הפסק המכונן בביטוי.'),
Q('מי כתב את קול העם?','השופט אגרנט',['הנשיא ברק','השופט שמגר','השופט חשין'],'קול העם נכתב בידי השופט אגרנט, שניסח בו את מבחן הוודאות הקרובה. הנשיאים שמגר וברק והשופט חשין פעלו בדור מאוחר, אחרי שההלכה כבר התגבשה, ולכן אינם כותבי הפסק.'),
Q('מהו מבחן ההגבלה שנקבע בקול העם?','ודאות קרובה לפגיעה ממשית בשלום הציבור',['חשש סביר לפגיעה','נטייה לפגיעה','כל ביקורת על הממשלה'],'בקול העם נקבע שהגבלת ביטוי מותרת רק כשיש ודאות קרובה לפגיעה ממשית בשלום הציבור. חשש סביר או נטייה לפגיעה הם מבחנים רפויים שאינם מצדיקים פגיעה בביטוי, וביקורת על הממשלה מוגנת מעצם טיבה.'),
Q('מה עשה שר הפנים בקול העם?','סגר שני עיתונים',['אסר הפגנה','סגר מפלגה','פיזר את הכנסת'],'בקול העם סגר שר הפנים שני עיתונים, קול העם ואל-איתיחאד, בטענה שפרסומיהם מסכנים את שלום הציבור, ובית המשפט ביטל את הצווים. איסור הפגנה, סגירת מפלגה או פיזור הכנסת אינם העובדות בפרשה.'),
Q('איזה ערך עמד מול חופש הביטוי בקול העם?','שלום הציבור',['קניין','חופש העיסוק','שוויון'],'בקול העם טען השר שהפרסומים מסכנים את שלום הציבור, וזה הערך שהועמד מול חופש הביטוי. חופש העיסוק, השוויון והקניין אינם הערכים שנבחנו כנגד הביטוי באותה פרשה.'),
Q('מהו הרציונל של "שוק הרעיונות"?','בתחרות חופשית האמת תצא לאור',['הגבלת רעיונות','מכירת עיתונים','הגנה על קניין'],'רציונל שוק הרעיונות גורס שבתחרות חופשית בין דעות האמת תצא לאור, ולכן יש להגן על הביטוי גם כשהדעה שנויה במחלוקת. הגבלת רעיונות סותרת רציונל זה, והגנת קניין או מכירת עיתונים אינן תוכנו.'),
Q('מהו הרציונל הדמוקרטי?','בחירה מושכלת וביקורת על השלטון דורשות ביטוי חופשי',['הגנה על קניין','מניעת פשיעה','תמיכה בממשלה'],'לפי הרציונל הדמוקרטי, בחירה מושכלת וביקורת על השלטון אפשריות רק כשיש ביטוי חופשי. מניעת פשיעה, הגנה על קניין ותמיכה בממשלה אינם הצדקה לחופש הביטוי, ותמיכה בממשלה אף מנוגדת לתפקידו כמבקר.'),
Q('מהו מימוש עצמי?','ביטוי כחלק מהאוטונומיה והכבוד של הפרט',['ביטוי כאמצעי תעמולה','ביטוי כנכס','ביטוי כחובה'],'מימוש עצמי הוא הרציונל שלפיו ביטוי הוא חלק מהאוטונומיה והכבוד של הפרט, ולכן ערך בפני עצמו. ביטוי כתעמולה, כחובה או כנכס אינו משקף את הרעיון שהביטוי משרת את האדם המביע.'),
Q('האם ביטוי פוגעני מוגן?','כן, והוא דווקא זקוק להגנה',['לא','רק אם הוא פוליטי','רק בכנסת'],'דווקא ביטוי פוגעני או מקומם זקוק להגנה, כי ביטוי נוח לשומעיו אינו מעורר ניסיונות להגבילו. הגבלת ההגנה לביטוי פוליטי בלבד או לכנסת בלבד מצמצמת אותה יותר מדי ומתעלמת מרציונלים של הזכות.'),
Q('בשניצר נקבע שהצנזור:','כפוף למבחן הוודאות הקרובה',['חופשי לפסול','כפוף לכנסת בלבד','אינו כפוף לדבר'],'בעניין שניצר נקבע שהצנזור הצבאי כפוף למבחן הוודאות הקרובה ואינו רשאי לפסול מידע בטענת ביטחון בלי לעמוד בו. הטענה שהצנזור חופשי לפסול או כפוף לכנסת בלבד סותרת את הביקורת השיפוטית.'),
Q('מה ההבדל בין ודאות קרובה לחשש?','ודאות קרובה מחמירה יותר',['אין הבדל','חשש מחמיר יותר','הכול תלוי בשר'],'ודאות קרובה דורשת הסתברות גבוהה לפגיעה ממשית, ואילו חשש הוא מבחן רפוי שדי בו בהסתברות נמוכה יותר. לכן ודאות קרובה מגינה על הביטוי טוב יותר, והטענה שהכול תלוי בשר מנוגדת לכלל שיפוטי.'),
Q('איזה סעיף בחוק העונשין עוסק בהסתה לגזענות?','ס׳ 144ב',['ס׳ 1','ס׳ 8','ס׳ 10'],'ס׳ 144ב לחוק העונשין עוסק בפרסום הסתה לגזענות, והוא דוגמה להגבלה מותרת על ביטוי. ס׳ 1, 8 ו-10 אינם הסעיף של הסתה לגזענות, ומי שבוחר בהם מבלבל בין סעיפים שונים.'),
Q('איזה ביטוי זוכה להגנה חזקה ביותר?','ביטוי פוליטי',['ביטוי מסחרי','ביטוי גס','ביטוי שקרי'],'ביטוי פוליטי הוא הקרוב ביותר לרציונל הדמוקרטי ולכן זוכה להגנה החזקה ביותר. ביטוי מסחרי, גס או שקרי נהנה מהגנה חלשה יותר, כי הוא רחוק יותר מליבת השיח הדמוקרטי.'),
Q('מהו המעמד החוקתי של חופש הביטוי?','זכות בלתי מנויה בעלת מעמד רם',['זכות מנויה בס׳ 7','אינו זכות חוקתית','זכות של אזרחים בלבד'],'חופש הביטוי אינו מנוי בחוק היסוד, אך הוכר כזכות בלתי מנויה בעלת מעמד רם, הכפופה לפסקת ההגבלה. ס׳ 7 עוסק בפרטיות, והזכות אינה מוגבלת לאזרחים ואינה נעדרת מעמד חוקתי.'),
Q('מתי ניתנה הלכת קול העם?','בשנת 1953, לפני העיגון החוקתי',['בשנת 1995','בשנת 1992','בשנת 2009'],'הלכת קול העם ניתנה ב-1953, כארבעים שנה לפני חוק יסוד: כבוד האדם וחירותו (1992), ולכן עוגנה בפסיקה ולא בחוק יסוד. 1992, 1995 ו-2009 הן שנים מאוחרות מאוד ואינן שנת פסק הדין.'),
Q('מה הסמכות שהשר השתמש בה בקול העם?','סמכות לסגור עיתון המסכן שלום הציבור',['סמכות להפקיע קרקע','סמכות להתיר חנויות','סמכות לשפוט'],'בקול העם השתמש השר בסמכות לסגור עיתון המסכן את שלום הציבור לפי פקודת העיתונות. הפקעת קרקע, שיפוט והיתר חנויות הן סמכויות אחרות שאינן קשורות לפרשה.'),
Q('כיצד פרש בית המשפט את סמכות השר?','בצמצום',['ברחבה','כחסרת גבולות','כשיקול דעת חופשי'],'בית המשפט פירש את סמכות השר בצמצום, כדי שלא תפגע בחופש הביטוי אלא במקרה של ודאות קרובה לפגיעה בשלום הציבור. פרשנות רחבה או שיקול דעת חופשי היו מאפשרים סגירת עיתונים לפי רצון השר.'),
Q('איזו הגבלה מקובלת על חופש הביטוי?','לשון הרע',['ביקורת על הממשלה','ביטוי פוליטי','ביטוי חדשותי'],'לשון הרע היא הגבלה מקובלת על הביטוי, כי היא מגינה על שם טוב. ביטוי פוליטי, חדשותי וביקורת על הממשלה הם ליבת הביטוי המוגן, ולכן אינם הגבלה מקובלת.'),
Q('מה היה הרקע לסגירת העיתונים בפרשת קול העם?','מאמרים ביקורתיים נגד הממשלה שהשר ראה בהם סכנה לשלום הציבור',['פרסום לשון הרע על אדם פרטי','פרסום מודעות מסחריות כוזבות','הפרת חובת רישוי עיתון'],'השר סגר את העיתונים בטענה שמאמריהם הביקורתיים נגד הממשלה מסכנים את שלום הציבור, ובית המשפט ביטל את הצווים בהחלת מבחן הוודאות הקרובה. לשון הרע על אדם פרטי, פרסומת כוזבת ורישוי אינם הרקע לפרשה.'),
Q('למה ביטוי פוליטי מוגן יותר?','הוא קרוב ביותר לרציונל הדמוקרטי',['הוא יקר יותר','הוא קצר יותר','הוא חדש יותר'],'ביטוי פוליטי קרוב ביותר לרציונל הדמוקרטי, שלפיו שיח חופשי מאפשר ביקורת על השלטון ובחירה מושכלת. יקר, חדש או קצר אינן תכונות משפטיות שמשפיעות על עוצמת ההגנה.'),
]
